    print(gcd(252, 105))
}

fn is_prime(n: Int) -> Bool {
    if n <= 1 { return false }
    for i in range(2, n) {
        if n % i == 0 { return false }
    }
    true
}
fn count_primes(limit: Int) -> Int {
    let mut count = 0
    for num in range(2, limit) {
        if is_prime(num) {
            count += 1
        }
    }
    count
}
